int d00_solution_blueprint_new(D00SolutionBlueprint *self, SpecDocument *doc, const char *document_version, char **err) {
  if (check_som_model_version(D00_SOLUTION_BLUEPRINT_MODEL_VERSION, document_version, err) != 0) {
    return 1;
  }
  som_node_init(&self->node, doc, "SBP");
  return 0;
}
const char *d00_solution_blueprint_object_model_version(const D00SolutionBlueprint *self) {
  (void)self;
  return D00_SOLUTION_BLUEPRINT_MODEL_VERSION;
}
SomEditability d00_solution_blueprint_editability_for(const char *document_version) {
  return som_editability_for(D00_SOLUTION_BLUEPRINT_MODEL_VERSION, document_version);
}
int d00_solution_blueprint_load_yaml(D00SolutionBlueprint *self, const char *yaml, SpecDocument **out_doc, char **err) {
  SpecDocument *doc = spec_document_from_yaml(yaml, d00_solution_blueprint_meta_tree(), err);
  if (doc == NULL) {
    return 1;
  }
  if (d00_solution_blueprint_new(self, doc, doc->model_version, err) != 0) {
    spec_document_free(doc);
    free(doc);
    return 1;
  }
  *out_doc = doc;
  return 0;
}
int d00_solution_blueprint_load_file(D00SolutionBlueprint *self, const char *path, SpecDocument **out_doc, char **err) {
  SpecDocument *doc = spec_document_from_file(path, d00_solution_blueprint_meta_tree(), err);
  if (doc == NULL) {
    return 1;
  }
  if (d00_solution_blueprint_new(self, doc, doc->model_version, err) != 0) {
    spec_document_free(doc);
    free(doc);
    return 1;
  }
  *out_doc = doc;
  return 0;
}
